@import "tailwindcss";

@theme {
  /* Deep-navy dark palette */
  --color-base: #070a14;
  --color-surface: #0d1322;
  --color-surface-2: #141c30;
  --color-line: rgba(255, 255, 255, 0.08);
  --color-muted: #8b93a7;
  --color-text: #e6e9f2;

  /* Blue / cyan / purple accents */
  --color-accent: #6366f1;
  --color-accent-2: #22d3ee;
  --color-accent-3: #a78bfa;

  --font-sans: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --font-display: "Plus Jakarta Sans", "Inter", system-ui, sans-serif;

  --animate-float: float 7s ease-in-out infinite;
  --animate-float-slow: float 11s ease-in-out infinite;
  --animate-gradient: gradient 9s ease infinite;
  --animate-pulse-ring: pulse-ring 2.4s ease-out infinite;
}

@keyframes float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-14px); }
}
@keyframes gradient {
  0%, 100% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
}
@keyframes pulse-ring {
  0% { transform: scale(0.8); opacity: 0.6; }
  100% { transform: scale(1.6); opacity: 0; }
}

@layer base {
  html {
    scroll-behavior: smooth;
  }
  body {
    margin: 0;
    background-color: var(--color-base);
    color: var(--color-text);
    font-family: var(--font-sans);
    line-height: 1.6;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }
  /* offset anchor targets for the fixed navbar */
  section {
    scroll-margin-top: 5.5rem;
  }
  ::selection {
    background: rgba(99, 102, 241, 0.35);
    color: #fff;
  }
  /* custom scrollbar */
  ::-webkit-scrollbar { width: 10px; }
  ::-webkit-scrollbar-track { background: var(--color-base); }
  ::-webkit-scrollbar-thumb {
    background: #1e293b;
    border-radius: 999px;
    border: 2px solid var(--color-base);
  }
  ::-webkit-scrollbar-thumb:hover { background: #334155; }
}

@layer components {
  /* Glassmorphism surfaces */
  .glass {
    background: rgba(255, 255, 255, 0.04);
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
    border: 1px solid var(--color-line);
  }
  .glass-card {
    background: linear-gradient(
      180deg,
      rgba(255, 255, 255, 0.05),
      rgba(255, 255, 255, 0.02)
    );
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
    border: 1px solid var(--color-line);
    border-radius: 1rem;
  }

  /* Gradient text */
  .gradient-text {
    background: linear-gradient(120deg, var(--color-accent-2), var(--color-accent), var(--color-accent-3));
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
    color: transparent;
  }

  /* Animated gradient border used on premium cards */
  .glow-ring {
    position: relative;
  }
  .glow-ring::before {
    content: "";
    position: absolute;
    inset: -1px;
    border-radius: inherit;
    padding: 1px;
    background: linear-gradient(135deg, rgba(34, 211, 238, 0.5), rgba(99, 102, 241, 0.5), rgba(167, 139, 250, 0.5));
    -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
    -webkit-mask-composite: xor;
    mask-composite: exclude;
    opacity: 0;
    transition: opacity 0.4s ease;
    pointer-events: none;
  }
  .glow-ring:hover::before { opacity: 1; }
}

@layer utilities {
  .bg-grid {
    background-image:
      linear-gradient(to right, rgba(255, 255, 255, 0.04) 1px, transparent 1px),
      linear-gradient(to bottom, rgba(255, 255, 255, 0.04) 1px, transparent 1px);
    background-size: 48px 48px;
  }
  .text-balance { text-wrap: balance; }
  .shadow-glow { box-shadow: 0 0 0 1px rgba(99, 102, 241, 0.2), 0 18px 50px -12px rgba(99, 102, 241, 0.35); }
}

