import { useEffect, useState } from "react"
import { motion, AnimatePresence } from "framer-motion"
import { Menu, X, Github, Linkedin } from "lucide-react"
import { profile } from "../data/profile"

const links = [
  { label: "About", href: "#about" },
  { label: "Skills", href: "#skills" },
  { label: "Projects", href: "#projects" },
  { label: "Education", href: "#education" },
  { label: "Certifications", href: "#certifications" },
  { label: "Contact", href: "#contact" },
]

export default function Navbar() {
  const [scrolled, setScrolled] = useState(false)
  const [open, setOpen] = useState(false)
  const [active, setActive] = useState("")

  useEffect(() => {
    const onScroll = () => {
      setScrolled(window.scrollY > 24)
      // active-section spy
      const ids = links.map((l) => l.href.slice(1))
      let current = ""
      for (const id of ids) {
        const el = document.getElementById(id)
        if (el && el.getBoundingClientRect().top <= 120) current = id
      }
      setActive(current)
    }
    window.addEventListener("scroll", onScroll, { passive: true })
    onScroll()
    return () => window.removeEventListener("scroll", onScroll)
  }, [])

  const close = () => setOpen(false)

  return (
    <motion.header
      initial={{ y: -80, opacity: 0 }}
      animate={{ y: 0, opacity: 1 }}
      transition={{ duration: 0.6, ease: [0.22, 1, 0.36, 1] }}
      className={`fixed inset-x-0 top-0 z-50 transition-all duration-300 ${
        scrolled ? "glass border-b border-[color:var(--color-line)]" : "bg-transparent"
      }`}
    >
      <nav className="mx-auto flex h-16 max-w-6xl items-center justify-between px-5 sm:px-8">
        <a href="#home" className="group flex items-center gap-2.5" onClick={close}>
          <span className="flex h-9 w-9 items-center justify-center rounded-lg bg-gradient-to-br from-[color:var(--color-accent-2)] to-[color:var(--color-accent)] font-[family-name:var(--font-display)] text-sm font-800 text-white shadow-glow">
            MA
          </span>
          <span className="hidden font-[family-name:var(--font-display)] text-sm font-700 tracking-wide text-text sm:block">
            Mohamed<span className="text-[color:var(--color-accent-2)]">.</span>
          </span>
        </a>

        {/* desktop nav */}
        <ul className="hidden items-center gap-1 md:flex">
          {links.map((l) => (
            <li key={l.href}>
              <a
                href={l.href}
                className={`relative rounded-lg px-3.5 py-2 text-sm font-500 transition-colors ${
                  active === l.href.slice(1)
                    ? "text-[color:var(--color-accent-2)]"
                    : "text-muted hover:text-text"
                }`}
              >
                {l.label}
                {active === l.href.slice(1) && (
                  <motion.span
                    layoutId="nav-active"
                    className="absolute inset-x-2 -bottom-0.5 h-0.5 rounded-full bg-gradient-to-r from-[color:var(--color-accent-2)] to-[color:var(--color-accent)]"
                  />
                )}
              </a>
            </li>
          ))}
        </ul>

        <div className="flex items-center gap-2">
          <a
            href={profile.github}
            target="_blank"
            rel="noreferrer"
            aria-label="GitHub"
            className="hidden h-9 w-9 items-center justify-center rounded-lg glass text-muted transition-colors hover:text-text sm:flex"
          >
            <Github className="h-4 w-4" />
          </a>
          <a
            href={profile.linkedin}
            target="_blank"
            rel="noreferrer"
            aria-label="LinkedIn"
            className="hidden h-9 w-9 items-center justify-center rounded-lg glass text-muted transition-colors hover:text-text sm:flex"
          >
            <Linkedin className="h-4 w-4" />
          </a>
          <a
            href="#contact"
            className="hidden rounded-lg bg-gradient-to-r from-[color:var(--color-accent)] to-[color:var(--color-accent-3)] px-4 py-2 text-sm font-600 text-white shadow-glow transition-transform hover:scale-105 md:inline-block"
          >
            Let's Connect
          </a>
          <button
            onClick={() => setOpen((v) => !v)}
            aria-label="Toggle menu"
            aria-expanded={open}
            className="flex h-9 w-9 items-center justify-center rounded-lg glass text-text md:hidden"
          >
            {open ? <X className="h-5 w-5" /> : <Menu className="h-5 w-5" />}
          </button>
        </div>
      </nav>

      {/* mobile menu */}
      <AnimatePresence>
        {open && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: "auto", opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={{ duration: 0.3 }}
            className="overflow-hidden glass border-t border-[color:var(--color-line)] md:hidden"
          >
            <ul className="flex flex-col gap-1 px-5 py-4">
              {links.map((l) => (
                <li key={l.href}>
                  <a
                    href={l.href}
                    onClick={close}
                    className="block rounded-lg px-3 py-2.5 text-sm font-500 text-muted hover:bg-white/5 hover:text-text"
                  >
                    {l.label}
                  </a>
                </li>
              ))}
              <li className="mt-2 flex gap-2">
                <a
                  href={profile.github}
                  target="_blank"
                  rel="noreferrer"
                  className="flex flex-1 items-center justify-center gap-2 rounded-lg glass px-3 py-2.5 text-sm font-500 text-text"
                >
                  <Github className="h-4 w-4" /> GitHub
                </a>
                <a
                  href={profile.linkedin}
                  target="_blank"
                  rel="noreferrer"
                  className="flex flex-1 items-center justify-center gap-2 rounded-lg glass px-3 py-2.5 text-sm font-500 text-text"
                >
                  <Linkedin className="h-4 w-4" /> LinkedIn
                </a>
              </li>
            </ul>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.header>
  )
}

import { motion } from "framer-motion"
import { Github, Linkedin, Mail, ArrowUpRight } from "lucide-react"
import SectionHeading from "./SectionHeading"
import { profile } from "../data/profile"
import { container, item } from "../lib/motion"

const cards = [
  {
    icon: Linkedin,
    label: "LinkedIn",
    value: "Connect with me",
    href: profile.linkedin,
    accent: "text-[color:var(--color-accent-2)]",
    highlight: true, // LinkedIn is the priority CTA per spec
  },
  {
    icon: Github,
    label: "GitHub",
    value: "See my code",
    href: profile.github,
    accent: "text-text",
  },
  {
    icon: Mail,
    label: "Email",
    value: profile.email,
    href: `mailto:${profile.email}`,
    accent: "text-[color:var(--color-accent-3)]",
  },
]

export default function Connect() {
  return (
    <section id="connect" className="relative py-24 sm:py-32">
      <div className="mx-auto max-w-6xl px-5 sm:px-8">
        <SectionHeading
          eyebrow="Professional Presence"
          title="Explore My Work"
          subtitle="The best way to see what I can do is to look at where I share it. Let's connect."
        />

        <motion.div
          variants={container}
          initial="hidden"
          whileInView="show"
          viewport={{ once: true, amount: 0.2 }}
          className="mt-14 grid gap-6 sm:grid-cols-2 lg:grid-cols-3"
        >
          {cards.map((c) => (
            <motion.a
              key={c.label}
              href={c.href}
              target={c.href.startsWith("mailto") ? undefined : "_blank"}
              rel="noreferrer"
              variants={item}
              whileHover={{ y: -8 }}
              className={`glass-card glow-ring group flex flex-col gap-5 rounded-2xl p-7 ${
                c.highlight ? "ring-1 ring-[color:var(--color-accent-2)]/40" : ""
              }`}
            >
              <div className="flex items-center justify-between">
                <span className={`flex h-14 w-14 items-center justify-center rounded-xl bg-gradient-to-br from-[color:var(--color-accent)]/15 to-[color:var(--color-accent-2)]/15 ${c.accent} transition-transform group-hover:scale-110`}>
                  <c.icon className="h-7 w-7" />
                </span>
                <ArrowUpRight className="h-5 w-5 text-muted transition-all group-hover:-translate-y-0.5 group-hover:translate-x-0.5 group-hover:text-text" />
              </div>
              <div>
                <p className="text-xs font-700 uppercase tracking-[0.18em] text-muted">
                  {c.label}
                </p>
                <p className="mt-1 font-[family-name:var(--font-display)] text-lg font-700 text-text">
                  {c.value}
                </p>
              </div>
              {c.highlight && (
                <span className="mt-auto inline-flex w-fit rounded-full bg-[color:var(--color-accent-2)]/10 px-3 py-1 text-[11px] font-600 text-[color:var(--color-accent-2)]">
                  Best way to reach me
                </span>
              )}
            </motion.a>
          ))}
        </motion.div>
      </div>
    </section>
  )
}

import { useState } from "react"
import { motion } from "framer-motion"
import { Send, Mail, Linkedin, Github, CheckCircle2, Loader2 } from "lucide-react"
import SectionHeading from "./SectionHeading"
import { profile } from "../data/profile"
import { fadeUp } from "../lib/motion"

// Functional contact form backed by Netlify Forms.
// Field names match the hidden <form name="contact"> in index.html so Netlify
// detects the form at build time and wires submissions to the site dashboard.
export default function Contact() {
  const [status, setStatus] = useState("idle") // idle | submitting | success | error
  const [form, setForm] = useState({ name: "", email: "", subject: "", message: "" })

  const update = (e) => setForm((f) => ({ ...f, [e.target.name]: e.target.value }))

  const handleSubmit = async (e) => {
    e.preventDefault()
    setStatus("submitting")

    const body = new URLSearchParams({
      "form-name": "contact",
      "bot-field": "",
      ...form,
    })

    try {
      const res = await fetch("/", {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body: body.toString(),
      })
      if (res.ok) {
        setStatus("success")
        setForm({ name: "", email: "", subject: "", message: "" })
      } else {
        setStatus("error")
      }
    } catch {
      setStatus("error")
    }
  }

  return (
    <section id="contact" className="relative py-24 sm:py-32">
      <div className="mx-auto max-w-6xl px-5 sm:px-8">
        <SectionHeading
          eyebrow="Contact"
          title="Let's Work Together"
          subtitle="Have a project, an opportunity, or simply want to connect? I'd love to hear from you."
        />

        <div className="mt-14 grid gap-8 lg:grid-cols-5">
          {/* form */}
          <motion.form
            variants={fadeUp}
            initial="hidden"
            whileInView="show"
            viewport={{ once: true, amount: 0.2 }}
            onSubmit={handleSubmit}
            name="contact"
            method="POST"
            data-netlify="true"
            netlify-honeypot="bot-field"
            className="glass-card glow-ring rounded-2xl p-6 sm:p-8 lg:col-span-3"
          >
            {/* honeypot */}
            <input type="hidden" name="form-name" value="contact" />
            <p className="hidden">
              <label>Don't fill this out: <input name="bot-field" onChange={update} /></label>
            </p>

            <div className="grid gap-5 sm:grid-cols-2">
              <Field label="Name" name="name" value={form.name} onChange={update} required />
              <Field label="Email" name="email" type="email" value={form.email} onChange={update} required />
            </div>
            <div className="mt-5">
              <Field label="Subject" name="subject" value={form.subject} onChange={update} required />
            </div>
            <div className="mt-5">
              <label className="mb-2 block text-sm font-600 text-text">Message</label>
              <textarea
                name="message"
                value={form.message}
                onChange={update}
                required
                rows={5}
                placeholder="Tell me about your project or opportunity..."
                className="w-full resize-y rounded-xl border border-[color:var(--color-line)] bg-white/5 px-4 py-3 text-sm text-text placeholder:text-muted/60 transition-colors focus:border-[color:var(--color-accent-2)]/60 focus:outline-none focus:ring-2 focus:ring-[color:var(--color-accent-2)]/20"
              />
            </div>

            <button
              type="submit"
              disabled={status === "submitting"}
              className="mt-6 inline-flex w-full items-center justify-center gap-2 rounded-xl bg-gradient-to-r from-[color:var(--color-accent)] to-[color:var(--color-accent-3)] px-6 py-3.5 text-sm font-600 text-white shadow-glow transition-transform hover:scale-[1.02] disabled:opacity-60 disabled:hover:scale-100"
            >
              {status === "submitting" ? (
                <>
                  <Loader2 className="h-4 w-4 animate-spin" /> Sending...
                </>
              ) : (
                <>
                  <Send className="h-4 w-4" /> Send Message
                </>
              )}
            </button>

            {status === "success" && (
              <motion.p
                initial={{ opacity: 0, y: 8 }}
                animate={{ opacity: 1, y: 0 }}
                className="mt-4 flex items-center gap-2 text-sm font-500 text-emerald-400"
              >
                <CheckCircle2 className="h-4 w-4" />
                Thank you! Your message has been sent — I'll get back to you soon.
              </motion.p>
            )}
            {status === "error" && (
              <p className="mt-4 text-sm font-500 text-rose-400">
                Something went wrong. Please try again, or email me directly at {profile.email}.
              </p>
            )}
          </motion.form>

          {/* direct contact */}
          <motion.div
            variants={fadeUp}
            initial="hidden"
            whileInView="show"
            viewport={{ once: true, amount: 0.2 }}
            className="flex flex-col gap-4 lg:col-span-2"
          >
            <p className="text-base leading-relaxed text-muted">
              Prefer a direct line? Reach me through any of these — I usually
              respond within a day or two.
            </p>

            <a
              href={`mailto:${profile.email}`}
              className="glass-card glow-ring flex items-center gap-4 rounded-2xl p-5 transition-transform hover:scale-[1.02]"
            >
              <span className="flex h-11 w-11 items-center justify-center rounded-xl bg-[color:var(--color-accent)]/15 text-[color:var(--color-accent-3)]">
                <Mail className="h-5 w-5" />
              </span>
              <span className="flex flex-col">
                <span className="text-xs font-600 uppercase tracking-wider text-muted">Email</span>
                <span className="text-sm font-600 text-text">{profile.email}</span>
              </span>
            </a>

            <a
              href={profile.linkedin}
              target="_blank"
              rel="noreferrer"
              className="glass-card glow-ring flex items-center gap-4 rounded-2xl p-5 transition-transform hover:scale-[1.02]"
            >
              <span className="flex h-11 w-11 items-center justify-center rounded-xl bg-[color:var(--color-accent-2)]/15 text-[color:var(--color-accent-2)]">
                <Linkedin className="h-5 w-5" />
              </span>
              <span className="flex flex-col">
                <span className="text-xs font-600 uppercase tracking-wider text-muted">LinkedIn</span>
                <span className="text-sm font-600 text-text">Connect with me</span>
              </span>
            </a>

            <a
              href={profile.github}
              target="_blank"
              rel="noreferrer"
              className="glass-card glow-ring flex items-center gap-4 rounded-2xl p-5 transition-transform hover:scale-[1.02]"
            >
              <span className="flex h-11 w-11 items-center justify-center rounded-xl bg-white/10 text-text">
                <Github className="h-5 w-5" />
              </span>
              <span className="flex flex-col">
                <span className="text-xs font-600 uppercase tracking-wider text-muted">GitHub</span>
                <span className="text-sm font-600 text-text">See my code</span>
              </span>
            </a>
          </motion.div>
        </div>
      </div>
    </section>
  )
}

function Field({ label, name, type = "text", value, onChange, required }) {
  return (
    <div>
      <label htmlFor={name} className="mb-2 block text-sm font-600 text-text">
        {label}
      </label>
      <input
        id={name}
        name={name}
